from pathlib import Path
import json,hashlib
out=Path(__file__).parent;r=out.parents[3];full=r/'review/semantic-kernel/sprint8/proof-inventory.json';v=json.loads(full.read_text())
def sha(b):return hashlib.sha256(b).hexdigest()
explicit=[{k:x[k] for k in ['name','statement','axioms','source','line','category','private'] if k in x} for x in v['theorems'] if x['declaration_origin']=='explicit'];assert len(explicit)==106
sources=sorted({x['source'] for x in v['theorems']+v['supplemental']});axioms=sorted({tuple(x['axioms']) for x in v['theorems']+v['supplemental']})
